async function api(path,{method='GET',body}={}){
  const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),15000);
  try{
    const response=await fetch(path,{method,credentials:'same-origin',signal:controller.signal,headers:body===undefined?{}:{'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});
    const data=await response.json();
    if(!response.ok){const error=new Error(data.error||t('loadError'));error.code=data.code;error.status=response.status;throw error;}
    return data;
  }catch(error){if(error.name==='AbortError')throw new Error(say('The local service did not respond. Try again.','De lokale service reageert niet. Probeer het opnieuw.'));throw error;}
  finally{clearTimeout(timer);}
}

async function session(role){
  if(state.roleReady===role)return;
  await api('/api/session',{method:'POST',body:{role}});state.roleReady=role;
}

function notice(message,error=false){
  const element=document.querySelector('#action-status');
  if(element){element.textContent=message;element.classList.toggle('is-error',error);}
}

function setBusy(button,busy,label){if(!button)return;button.disabled=busy;if(label)button.innerHTML=esc(label);}
async function go(path){
 if(path===location.pathname+location.search+location.hash)return;
 if(!await allowLeave())return;
 document.querySelectorAll('dialog[open]').forEach(dialog=>dialog.close());history.pushState({},'',path);route();
}
async function allowLeave(){
 if(!state.dirty)return true;
 return new Promise(resolve=>{
  const dialog=document.createElement('dialog');dialog.className='experiment-dialog';
  dialog.innerHTML=`<div class="dialog-heading"><h2>${esc(say('Save your changes?','Wijzigingen opslaan?'))}</h2></div><p class="subtitle">${esc(say('Your changes have not been saved.','Je wijzigingen zijn nog niet opgeslagen.'))}</p><p class="form-error" role="alert"></p><div class="dialog-actions"><button class="button" data-leave="stay">${esc(say('Keep editing','Verder bewerken'))}</button><button class="button" data-leave="discard">${esc(say('Discard changes','Wijzigingen verwijderen'))}</button><button class="button primary" data-leave="save">${esc(say('Save and leave','Opslaan en verlaten'))}</button></div>`;
  document.body.append(dialog);let decision=false;
  dialog.onclose=()=>{dialog.remove();resolve(decision);};
  dialog.querySelectorAll('[data-leave]').forEach(button=>button.onclick=async()=>{
   if(button.dataset.leave==='stay'){dialog.close();return;}
   if(button.dataset.leave==='save'){
    button.disabled=true;
    try{if(state.role==='moderator'){state.draft=await api(modPath('/draft'),{method:'PUT',body:state.draft});}else{state.study=await api(`/api/researcher/studies/${encodeURIComponent(state.study.id)}`,{method:'PUT',body:evenStudyPayload(state.study)});}}
    catch(error){dialog.querySelector('.form-error').textContent=error.message;button.disabled=false;return;}
   }
   state.dirty=false;decision=true;dialog.close();
  });dialog.showModal();
 });
}

