function metricCard(image,label,value,note=''){return `<article class="metric"><div class="metric-label">${icon(image,17)}${esc(label)}</div><div class="metric-value ${value==='—'?'is-unavailable':''}">${esc(value==='—'?say('Not enough data','Nog niet genoeg gegevens'):value)}</div><p>${esc(note)}</p></article>`;}
