function dominantDuration(row){const values=(row.duration||[]).filter(item=>typeof item.count==='number');return values.length?values.reduce((a,b)=>a.count>=b.count?a:b).label:'—';}
function reportTable(report){
 if(!report?.rows?.length)return empty(t('noData'),say('Results will appear after interventions are shown.','Resultaten verschijnen nadat interventies zijn getoond.'));
 const hidden=value=>value==null?`<span class="wk-hidden-value">${esc(say('Hidden for privacy','Afgeschermd voor privacy'))}</span>`:fmt(value);
 return `<div class="table-scroll"><table><thead><tr><th>${esc(t('variant'))}</th><th>${esc(t('shown'))}</th><th>${esc(t('help'))}</th><th>${esc(t('helpRate'))}</th><th>${esc(t('completionRate'))}</th></tr></thead><tbody>${orderedRows(report).map((row,i)=>`<tr><td><span class="variant-id ${i%2?'sage':''}">${esc(row.armId==='default'?'D':row.armId)}</span><strong>${esc(row.name||row.armId)}</strong><small class="wk-version-label">${esc(versionLabel(row.studyRevision))}</small></td><td>${hidden(row.counts?.shown)}</td><td>${hidden(row.counts?.help_selected)}</td><td>${row.rates?.help_rate==null?hidden(null):pct(row.rates.help_rate)}</td><td>${row.rates?.completion_rate==null?hidden(null):pct(row.rates.completion_rate)}</td></tr>`).join('')}</tbody></table></div>`;
}
function orderedRows(report){return [...(report?.rows||[])].sort((a,b)=>a.studyRevision.localeCompare(b.studyRevision)||a.armId.localeCompare(b.armId));}
function versionLabel(key){return key?`${t('version')} ${String(key).split('@').at(-1)}`:t('noPublish');}
