function reportQuery(){const q=new URLSearchParams({source:state.source});if(state.reportPublication)q.set('publication',state.reportPublication);if(state.reportPeriod!=='all'){q.set('from',new Date(Date.now()-(state.reportPeriod==='week'?6:29)*86400000).toISOString().slice(0,10));q.set('to',new Date().toISOString().slice(0,10));}return q.toString();}
function comparison(report){
 const rows=orderedRows(report);if(rows.length<2)return '';
 const groups=new Set(rows.map(row=>row.studyRevision));if(groups.size>1)return `<div class="wk-comparison-note">${esc(say('Select one version to compare its variants.','Kies één versie om de varianten te vergelijken.'))}</div>`;
 const primary=state.role==='researcher'?(state.study.publications?.find(p=>p.key===rows[0]?.studyRevision)?.primary||state.study.primary):'help_rate';const label=primary==='completion_rate'?t('completionRate'):t('helpRate');const first=rows[0]?.rates?.[primary];
 return `<section class="panel wk-comparison" id="comparison-summary" data-testid="outcome-comparison"><div class="panel-heading"><div><h2>${esc(say('Compare variants','Varianten vergelijken'))}</h2><p>${esc(label)}</p></div>${infoButton('report',say('How to read this comparison','Hoe lees je deze vergelijking'))}</div><div class="wk-comparison-rows">${rows.map((row,i)=>{const rate=row.rates?.[primary];const difference=rate==null||first==null?null:Math.round((rate-first)*10)/10;return `<div class="wk-comparison-row"><div><span class="variant-id">${esc(row.armId)}</span><strong>${esc(row.name)}</strong></div><span class="wk-rate-track"><i style="width:${rate==null?0:rate}%"></i></span><strong>${rate==null?esc(say('Hidden','Afgeschermd')):pct(rate)}</strong><span>${i===0?esc(say('Reference','Referentie')):difference==null?'—':`${difference>0?'+':''}${difference.toFixed(1)} ${esc(say('pp vs '+rows[0].armId,'pp t.o.v. '+rows[0].armId))}`}</span></div>`;}).join('')}</div></section>`;
}

function engagementTable(report){
 const rows=orderedRows(report);
 const cell=(rate,numerator,denominator)=>rate==null?`<span class="wk-hidden-value">${esc(say('Not enough data','Nog niet genoeg gegevens'))}</span>`:`<strong>${pct(rate)}</strong><small>${fmt(numerator)} / ${fmt(denominator)}</small>`;
 return `<section class="panel wk-engagement" id="engagement-table" data-testid="engagement-results"><div class="panel-heading"><div><h2>${esc(say('Engagement and retention','Betrokkenheid en retentie'))}</h2><p>${esc(say('What happened within each intervention.','Wat er binnen elke interventie gebeurde.'))}</p></div>${infoButton('engagement',say('How engagement is measured','Hoe betrokkenheid wordt gemeten'))}</div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>${esc(t('variant'))}</th><th>${esc(say('Visible ≥30s','Zichtbaar ≥30s'))}</th><th>${esc(say('Scrolled in information step','Gescrold in informatiestap'))}</th><th>${esc(say('Message end reached','Berichteinde bereikt'))}</th></tr></thead><tbody>${rows.map(row=>{const duration=row.duration||[];const allDurations=duration.length===4&&duration.every(bin=>typeof bin.count==='number');const denominator=allDurations?duration.reduce((sum,bin)=>sum+bin.count,0):null;const retained=allDurations?duration.slice(2).reduce((sum,bin)=>sum+bin.count,0):null;return `<tr><td><span class="variant-id">${esc(row.armId==='default'?'D':row.armId)}</span><strong>${esc(row.name)}</strong></td><td>${cell(row.rates?.retention_30s_rate,retained,denominator)}</td><td>${cell(row.rates?.scroll_rate,row.counts?.scrolled,row.counts?.engagement_measured)}</td><td>${cell(row.rates?.message_end_rate,row.counts?.education_end_viewed,row.counts?.engagement_measured)}</td></tr>`;}).join('')}</tbody></table></div>`:empty(t('noData'),say('Engagement appears after measured interventions.','Betrokkenheid verschijnt na gemeten interventies.'))}</section>`;
}

function analytics(research=false){
 const report=state.report;const c=reportCounts(report);const keys=[...new Set([...(report?.rows||[]).map(row=>row.studyRevision),...(research?state.study.publications||[]:state.site.publications||[]).map(p=>p.key)])];
 return `${pageTitle('',research?state.study.name:t('analytics'),research?say('Compare the outcomes of your message variants.','Vergelijk de uitkomsten van je berichtvarianten.'):say('See what happens after an intervention is shown.','Bekijk wat er gebeurt nadat een interventie is getoond.'),`<button class="button" data-action="export">${icon('download',16)} ${esc(t('export'))}</button>${research?`<a class="button" href="/researcher/studies/${state.study.id}/editor" data-nav>${esc(say('Edit study','Onderzoek bewerken'))}</a>`:''}`)}${research?studyNavigation('results'):''}<div class="wk-report-toolbar"><div class="wk-report-filters">${sourceSelect()}<label class="wk-inline-label">${esc(say('Period','Periode'))}<select id="report-period"><option value="all" ${state.reportPeriod==='all'?'selected':''}>${esc(say('All time','Alle tijd'))}</option><option value="week" ${state.reportPeriod==='week'?'selected':''}>${esc(say('Last 7 days','Laatste 7 dagen'))}</option><option value="month" ${state.reportPeriod==='month'?'selected':''}>${esc(say('Last 30 days','Laatste 30 dagen'))}</option></select></label><label class="wk-inline-label">${esc(t('version'))}<select id="report-publication"><option value="">${esc(say('All versions','Alle versies'))}</option>${keys.map(key=>`<option value="${attr(key)}" ${state.reportPublication===key?'selected':''}>${esc(versionLabel(key))}${research?'':` · ${esc(String(key).startsWith('site:')?say('Default message','Standaardbericht'):say('Study','Onderzoek'))}`}</option>`).join('')}</select></label></div>${infoButton('report',say('About these results','Over deze resultaten'))}</div>${comparison(report)}${metricCards(report)}<section class="panel"><div class="panel-heading"><h2>${esc(say('Outcome details','Uitkomsten'))}</h2></div>${reportTable(report)}</section>${research?engagementTable(report):''}<details class="wk-detail-section"><summary>${esc(say('Time and journey details','Tijd en stappen bekijken'))}</summary><div class="wk-overview-columns wk-report-section">${distribution(t('duration'),report?.totals?.duration||[])}${distribution(t('stageCounts'),[{label:t('reflection'),count:c.reflection_viewed},{label:t('understanding'),count:c.education_viewed},{label:t('support'),count:c.support_viewed}])}</div><p class="wk-small-note">${esc(say('Exit button used','Afsluitknop gebruikt'))}: ${fmt(c.exited)}</p></details>`;
}

function draftIndicator(){return `<span class="badge subtle" id="draft-indicator">${esc(state.dirty?t('unsaved'):say('Saved draft','Opgeslagen concept'))}</span>`;}
function stageName(stage){return ({reflection:t('reflection'),education:t('understanding'),support:t('support')})[stage];}
function builderSwitch(){return `<div class="wk-builder-switch segmented"><button data-builder-tab="edit" class="${state.builderTab==='edit'?'selected':''}">${esc(t('edit'))}</button><button data-builder-tab="preview" class="${state.builderTab==='preview'?'selected':''}">${esc(t('preview'))}</button></div>`;}

function previewPanel(){return `<section class="preview-column wk-preview-column"><div class="preview-toolbar"><strong>${esc(t('preview'))}</strong><div class="inline-actions"><div class="segmented" aria-label="${attr(t('preview'))}"><button type="button" data-viewport="desktop" class="${state.viewport==='desktop'?'selected':''}">${esc(t('desktop'))}</button><button type="button" data-viewport="mobile" class="${state.viewport==='mobile'?'selected':''}">${esc(t('mobile'))}</button></div>${infoButton('preview',say('Preview options','Voorbeeldopties'))}</div></div><div id="shared-preview" class="wk-shared-preview ${state.viewport==='mobile'?'is-mobile':''}"></div></section>`;}

function interventionControls(intervention){
 const lang=state.editLanguage;const fields=intervention[lang]||DEFAULT_INTERVENTION[lang];if(!intervention.order.includes(state.editStage))state.editStage=intervention.order[0];const stage=state.editStage;
 return `<div class="wk-editor-tabs"><div class="segmented" aria-label="${attr(t('languages'))}"><button type="button" data-edit-language="en" class="${lang==='en'?'selected':''}">English</button><button type="button" data-edit-language="nl" class="${lang==='nl'?'selected':''}">Nederlands</button></div></div><div class="wk-stage-tabs" role="group" aria-label="${attr(say('Message stage','Berichtstap'))}">${intervention.order.map(key=>`<button type="button" data-edit-stage="${key}" data-testid="edit-stage-${key}" class="${stage===key?'selected':''}" aria-pressed="${stage===key}">${esc(stageName(key))}</button>`).join('')}</div>${stage==='reflection'?`${field(t('title'),'copy:title',fields.title)}${field(t('body'),'copy:body',fields.body,{area:true})}${field(t('button'),'copy:button',fields.button)}`:stage==='education'?`${field(t('title'),'copy:educationTitle',fields.educationTitle)}${field(t('body'),'copy:educationBody',fields.educationBody,{area:true})}${intervention.country==='NL'?toggle(t('legal'),'option:legal',intervention.legal,say('Uses the reviewed facts for the selected country.','Gebruikt gecontroleerde feiten voor het geselecteerde land.')):`<p class="field-hint">${esc(say('No reviewed legal content is available for this country.','Er is geen gecontroleerde juridische inhoud voor dit land.'))}</p>`}`:`${field(t('title'),'copy:helpTitle',fields.helpTitle)}${field(t('body'),'copy:helpBody',fields.helpBody,{area:true})}<p class="field-hint">${esc(say('Support services follow the visitor’s selected country.','Hulpdiensten volgen het door de bezoeker gekozen land.'))}</p>`}<details class="wk-editor-details" id="advanced-settings"><summary>${esc(say('Advanced settings','Geavanceerde instellingen'))}</summary>${intervention.layout==='plain'?`<p class="field-hint">${esc(say('Information and support are on the same page.','Informatie en hulp staan op dezelfde pagina.'))}</p>`:select(t('order'),'option:order',ORDERS.findIndex(order=>order.join()===intervention.order.join()),[['0',t('reflectionFirst')],['1',t('educationFirst')],['2',t('educationOnly')]])}${select(t('country'),'option:country',intervention.country,[['NL',t('netherlands')],['OTHER',t('unknownCountry')]])}${select(t('layout'),'option:layout',intervention.layout,[['reading',say('Calm reading layout','Rustige leesindeling')],['plain',say('Plain single page','Eenvoudige enkele pagina')],['meaning',say('Meaning and values','Betekenis en waarden')],['scene',say('Animated scenes','Geanimeerde scènes')]])}${['plain','meaning'].includes(intervention.layout)?'':toggle(t('motion'),'motion:enabled',intervention.motion?.enabled)}${intervention.motion?.enabled&&!['plain','meaning'].includes(intervention.layout)?`<div class="wk-form-row">${select(t('transition'),'motion:transition',intervention.motion.transition||'fade',[['none',t('none')],['fade',t('fade')],['slide',t('slide')]])}${field(`${t('sceneHold')} (${t('seconds')})`,'motion:holdSeconds',intervention.motion.holdSeconds||5,{type:'number',min:2,max:10,step:1})}</div>`:''}</details>`;
}

function moderatorEditor(){
 const message=state.draft;if(!message.order.includes(state.editStage))state.editStage=message.order[0];if(state.selectedMessageBlock!=='main'&&!stageBlocks(message,state.editStage).some(block=>block.id===state.selectedMessageBlock))state.selectedMessageBlock='main';
 const changed=JSON.stringify(message)!==JSON.stringify(state.site.intervention);
 return `${pageTitle('',say('Message builder','Berichtbewerker'),say('Shape the experience, edit the details, and publish when it feels right.','Geef de ervaring vorm, bewerk de inhoud en publiceer wanneer je tevreden bent.'),`<button class="button" data-action="save-default" ${!state.dirty?'disabled':''}>${esc(t('save'))}</button><button class="button primary" data-action="review-default" ${!changed?'disabled':''}>${esc(say('Review and publish','Controleren en publiceren'))}${icon('arrow',15)}</button>`)}${moderatorBuilderView({message,language:state.language,editLanguage:state.editLanguage,stage:state.editStage,selectedBlock:state.selectedMessageBlock,inspectorTab:state.messageInspectorTab,mode:state.messageMode,builderTab:state.builderTab,viewport:state.viewport,templateFilter:state.messageTemplateFilter,selectedTemplate:state.selectedMessageTemplate,canUndo:state.builderPast.length>0,canRedo:state.builderFuture.length>0})}`;
}

function studyCard(study){const publication=study.publications?.at(-1);const n=study.participation?.platforms||0;return `<article class="panel wk-study-row"><div><div class="inline-actions">${badge(statusLabel(study.status),study.status==='running'?'sage':'subtle')}<span class="meta">${esc(versionLabel(publication?.key))}</span></div><h2><a href="/researcher/studies/${encodeURIComponent(study.id)}/editor" data-nav>${esc(study.name)}</a></h2><p>${esc(study.hypothesis)}</p><span class="wk-study-stats">${study.arms.length} ${esc(say('variants','varianten'))} · ${esc(study.primary==='completion_rate'?t('completionRate'):t('helpRate'))} · ${n} ${esc(say('platforms on this version','platforms op deze versie'))}</span></div><div class="inline-actions"><a class="button" href="/researcher/studies/${encodeURIComponent(study.id)}/editor" data-nav>${esc(t('edit'))}</a><a class="button primary" href="/researcher/studies/${encodeURIComponent(study.id)}/results" data-nav>${esc(t('results'))}${icon('arrow',14)}</a></div></article>`;}

function studyList(){return `${pageTitle('',t('studies'),say('Create message variants and compare outcomes across participating platforms.','Maak berichtvarianten en vergelijk uitkomsten op deelnemende platforms.'),`<a class="button" href="/researcher/lab" data-nav>${esc(say('Research lab','Onderzoekslab'))}${icon('flask',16)}</a><button class="button primary" data-action="create-study">${icon('plus',17)} ${esc(t('create'))}</button>`)}${state.studies.length?state.studies.map(studyCard).join(''):empty(t('noStudies'),t('noStudiesHint'),`<button class="button primary" data-action="create-study">${esc(t('create'))}</button>`)}`;}
function studyNavigation(view){return `<nav class="wk-study-navigation" aria-label="${attr(say('Study navigation','Onderzoeksnavigatie'))}">${[['editor',say('Design study','Onderzoek ontwerpen')],['platforms',say('Platforms','Platforms')],['results',t('results')]].map(([key,label])=>`<a href="/researcher/studies/${encodeURIComponent(state.study.id)}/${key}" data-nav class="${view===key?'selected':''}">${esc(label)}</a>`).join('')}</nav>`;}

function messagePresets(){
 const arm=state.study.arms[state.selectedArm];const undo=state.presetUndo?.studyId===state.study.id&&state.presetUndo?.armId===arm.id;const active=arm.intervention.layout==='plain'?'plain':arm.intervention.layout==='meaning'?'meaning':'calm';
 return `<section class="wk-experience-presets"><h3>${esc(say('Choose an experience','Kies een ervaring'))}</h3><p>${esc(say('A complete starting point for this variant. You can edit it afterwards.','Een compleet startpunt voor deze variant. Je kunt het daarna bewerken.'))}</p><div class="wk-experience-grid">${EXPERIENCE_PRESETS.map(preset=>`<button type="button" data-experience-preset="${preset.id}" class="wk-experience-card" aria-pressed="${active===preset.id}" ${state.study.status==='ended'?'disabled':''}><span class="wk-experience-poster poster-${preset.id}" aria-hidden="true">${preset.id==='plain'?`<span>${esc(say('Information','Informatie'))}</span><i></i><i></i><i></i>`:preset.id==='calm'?`${icon('pause',23)}<span>${esc(say('Look away. Pause.','Kijk weg. Pauzeer.'))}</span>`:`<span>${esc(say('Your time.','Jouw tijd.'))}<br>${esc(say('Your life.','Jouw leven.'))}</span>`}</span><strong>${esc(local(preset.name))}</strong><small>${esc(local(preset.description))}</small></button>`).join('')}</div>${undo?`<button class="text-link" type="button" data-action="undo-message-preset">${esc(say('Undo last preset','Laatste sjabloon ongedaan maken'))}</button>`:''}</section><details class="wk-message-presets"><summary>${esc(say('More wording styles','Meer tekststijlen'))}</summary><div class="wk-preset-grid">${MESSAGE_PRESETS.map(preset=>`<button type="button" data-message-preset="${preset.id}" ${state.study.status==='ended'?'disabled':''}><strong>${esc(local(preset.name))}</strong><small>${esc(local(preset.description))}</small></button>`).join('')}</div></details>`;
}

function studyPlatforms(){
 const data=state.studyPlatforms;const publication=state.study.publications?.at(-1);const available=state.study.status==='running';
 return `${pageTitle('',state.study.name,say('Choose which of your connected platforms use this published version.','Kies welke aangesloten platforms deze gepubliceerde versie gebruiken.'))}${studyNavigation('platforms')}<section class="panel wk-platform-list"><div class="panel-heading"><div><h2>${esc(say('Connected platforms','Aangesloten platforms'))}</h2><p>${esc(publication?`${versionLabel(publication.key)} · ${say('New views are assigned automatically.','Nieuwe vertoningen worden automatisch toegewezen.')}`:say('Publish your study to enable it on a platform.','Publiceer het onderzoek om het op een platform in te schakelen.'))}</p></div>${infoButton('platforms',say('About platform approval','Over platformtoestemming'))}</div>${(data?.platforms||[]).map(platform=>{
 const ownsEnabled=platform.activeStudy?.id===state.study.id&&platform.enrolment?.enabled;
 const label=platform.onCurrentVersion?say('Enabled','Ingeschakeld'):ownsEnabled?say('Older version','Oudere versie'):platform.activeStudy?say('Another study','Ander onderzoek'):say('Default message','Standaardbericht');
 return `<div class="wk-platform-row"><div>${icon(platform.id==='wordpress'?'plug':'globe',22)}<div><strong>${esc(platform.name)}</strong><small>${esc(platform.country==='NL'?t('netherlands'):t('unknownCountry'))}${platform.activeStudy?` · ${esc(platform.activeStudy.name)}`:''}</small></div></div><div class="inline-actions">${badge(label,platform.onCurrentVersion?'sage':'subtle')}${ownsEnabled?`<button class="button" data-action="withdraw-platform" data-site-id="${attr(platform.id)}" data-study-revision="${attr(platform.enrolment.studyRevision)}">${esc(say('Disable study','Onderzoek uitschakelen'))}</button>`:''}${!platform.onCurrentVersion?`<button class="button primary" data-action="review-platform-enrol" data-site-id="${attr(platform.id)}" ${!publication||!available?'disabled':''}>${esc(say('Review and enable','Controleren en inschakelen'))}</button>`:''}</div></div>`;
 }).join('')}</section>`;
}

function researchEditor(){
 const study=state.study;const arm=study.arms[state.selectedArm]||study.arms[0];const ended=study.status==='ended';const step=state.composerStep;const n=study.participation?.platforms||0;const unpublished=!study.publications?.length||JSON.stringify(studyPayload(study))!==JSON.stringify(studyPayload(study.publications.at(-1)));
 const steps=[['setup',say('Study setup','Onderzoek instellen')],['messages',say('Messages','Berichten')],['review',say('Review and publish','Controleren en publiceren')]];
 const headerActions=`<button class="button" data-action="save-study" ${ended||!state.dirty?'disabled':''}>${esc(t('save'))}</button>${step==='review'?`<button class="button primary" data-action="publish-study" ${ended||!unpublished?'disabled':''}>${icon('check',15)} ${esc(t('publish'))}</button>`:`<button class="button primary" data-composer-step="${step==='setup'?'messages':'review'}">${esc(say('Continue','Verder'))}${icon('arrow',15)}</button>`}`;
 let body='';
 if(step==='setup')body=`<section class="panel wk-study-meta"><form id="study-meta" ${ended?'inert':''}>${field(say('Study name','Onderzoeksnaam'),'study:name',study.name)}${field(t('hypothesis'),'study:hypothesis',study.hypothesis,{area:true})}${select(t('primary'),'study:primary',study.primary,[['help_rate',t('helpRate')],['completion_rate',t('completionRate')]])}<div class="wk-study-meta-footer"><span>English · Nederlands / ${esc(t('netherlands'))}</span></div></form></section>`;
 if(step==='messages')body=`<div class="wk-arm-toolbar"><div class="wk-arm-tabs" role="group" aria-label="${attr(t('selectVariant'))}">${study.arms.map((item,i)=>`<button class="${state.selectedArm===i?'selected':''}" data-arm="${i}" aria-pressed="${state.selectedArm===i}"><span>${esc(item.id)}</span>${esc(item.name)}</button>`).join('')}</div><button class="button small" data-action="add-arm" ${study.arms.length>=4||ended?'disabled':''}>${icon('plus',15)} ${esc(t('addVariant'))}</button></div>${builderSwitch()}<div class="builder-layout wk-builder-layout" data-builder-view="${state.builderTab}"><section class="panel editor-panel"><div class="panel-heading"><h2>${esc(t('variant'))} ${esc(arm.id)}</h2>${draftIndicator()}</div><form id="arm-editor" ${ended?'inert':''}>${field(t('armName'),'arm:name',arm.name)}<details class="mb-research-templates"><summary>${esc(say('Start from a template','Begin met een sjabloon'))}</summary>${messagePresets()}</details>${interventionControls(arm.intervention)}${study.arms.length>2?`<button class="text-link wk-remove-arm" data-action="remove-arm" type="button" ${ended?'disabled':''}>${icon('close',14)} ${esc(t('removeVariant'))}</button>`:''}</form></section>${previewPanel()}</div>`;
 if(step==='review')body=`<section class="panel wk-review-summary"><div class="panel-heading"><div><h2>${esc(say('Ready to publish?','Klaar om te publiceren?'))}</h2><p>${esc(say('Review every variant in English and Dutch. Publishing creates a version you can review on your connected platforms.','Controleer elke variant in het Engels en Nederlands. Publiceren maakt een versie die je op je aangesloten platforms kunt controleren.'))}</p></div>${draftIndicator()}</div><div class="wk-review-variants">${study.arms.map(item=>`<article><span class="variant-id">${esc(item.id)}</span><strong>${esc(item.name)}</strong><p>${esc(firstHeadline(item.intervention,state.editLanguage))}</p><small>${esc(item.intervention.order.map(stageName).join(' → '))}</small></article>`).join('')}</div><div class="panel-foot"><button class="button" data-action="preview-draft-study">${icon('eye',16)} ${esc(say('Preview all variants','Alle varianten bekijken'))}</button><span>${esc(t('primary'))}: ${esc(study.primary==='help_rate'?t('helpRate'):t('completionRate'))}</span></div></section><p class="wk-small-note">${esc(say('A new version must be reviewed before it replaces the version already enabled on a platform.','Een nieuwe versie moet worden gecontroleerd voordat deze de ingeschakelde versie vervangt.'))}</p>`;
 return `${pageTitle('',study.name,`${n} ${say('platforms on this version','platforms op deze versie')} · ${statusLabel(study.status)}`,headerActions)}${studyNavigation('editor')}<div class="wk-composer-steps" role="group" aria-label="${attr(say('Study steps','Onderzoeksstappen'))}">${steps.map(([key,label],i)=>`<button data-composer-step="${key}" class="${step===key?'selected':''}" aria-pressed="${step===key}"><span>${i+1}</span>${esc(label)}</button>`).join('')}</div>${ended?`<p class="notice">${esc(t('completionHint'))}</p>`:''}${body}<details class="wk-study-actions"><summary>${esc(say('Study actions','Onderzoeksacties'))}</summary><div class="inline-actions"><button class="button small" data-action="duplicate-study">${icon('copy',15)} ${esc(t('duplicate'))}</button>${study.publications?.length&&!ended?`<button class="button small" data-action="study-status" data-status="${study.status==='running'?'paused':'running'}">${icon(study.status==='running'?'pause':'play',14)} ${esc(study.status==='running'?t('pause'):say('Open for participation','Openstellen voor deelname'))}</button><button class="button small" data-action="study-status" data-status="ended">${esc(t('complete'))}</button>`:''}</div></details>`;
}

function moderatorPreview(){const dialog=document.createElement('dialog');dialog.className='experiment-dialog wk-variant-dialog';dialog.innerHTML=`<div class="dialog-heading"><h2>${esc(say('Your published default','Je gepubliceerde standaard'))}</h2><button class="icon-button" data-close aria-label="${attr(t('close'))}">${icon('close',18)}</button></div><div id="default-published-preview" class="wk-shared-preview"></div>`;document.body.append(dialog);const dispose=renderPreview(dialog.querySelector('#default-published-preview'),state.site.intervention,{language:state.language,country:state.site.country,services:helpServices.filter(service=>service.country==='NL'&&service.verified),legalPack:legalPacks.find(pack=>pack.country==='NL')});dialog.onclose=()=>{dispose();dialog.remove();};dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.showModal();}

function connectionForm(){return `<details class="panel wk-connection" id="settings"><summary>${esc(say('Platform settings','Platforminstellingen'))}</summary><form id="connection-form"><div class="wk-form-row">${field(say('Platform name','Platformnaam'),'name',state.site.name)}${select(say('Default country','Standaardland'),'country',state.site.country,[['NL',t('netherlands')],['OTHER',t('unknownCountry')]])}</div>${field(say('Allowed website origins','Toegestane website-oorsprongen'),'origins',(state.site.origins||[]).join('\n'),{area:true})}${field(say('Return page URL','URL van terugkeerpagina'),'returnUrl',state.site.returnUrl)}<div class="wk-form-actions"><span class="field-hint">${esc(say('One website origin per line. Include the scheme and port.','Eén website-oorsprong per regel. Vermeld het protocol en de poort.'))}</span><button class="button primary" type="submit">${esc(t('saveConnection'))}</button></div></form></details>`;}
function integrationStatus(item){return item.status==='Tested'?say('Ready to install','Klaar voor installatie'):item.id==='discord'?say('Bot package','Botpakket'):item.status==='Recipe'?say('Setup guide','Installatiehandleiding'):say('Planned','Gepland');}
function integrationCard(item){return `<a class="panel integration-card wk-integration-link" href="/moderator/docs/${encodeURIComponent(item.id)}" data-nav><div class="section-heading"><span class="wk-logo"><img src="${attr(item.icon)}" width="31" height="31" alt="" loading="lazy"></span>${badge(integrationStatus(item),item.status==='Tested'?'sage':'subtle')}</div><h3>${esc(item.name)}</h3><span class="wk-card-action">${esc(say('Set up','Instellen'))} ${icon('arrow',15)}</span></a>`;}
function deploymentPanel(){const d=state.deployment;const status=d?.verification?.status||'not_checked';const verified=status==='verified';return `<section class="panel wk-deployment" id="deployment"><div class="panel-heading"><div><h2>${esc(say('Verify your deployment','Controleer je installatie'))}</h2><p>${esc(say('Check the service, then follow a test submission from your website to the intervention.','Controleer de service en volg daarna een test vanaf je website naar de interventie.'))}</p></div><button class="button primary" data-action="check-deployment" data-testid="deployment-check">${icon('check',16)} ${esc(status==='checking'?say('Restart check','Controle herstarten'):say('Run deployment check','Installatie controleren'))}</button></div><div id="deployment-status" aria-live="polite">${d?`<div class="wk-check-list">${d.checks.map(check=>`<div><span class="wk-check-icon ${check.status==='passed'?'passed':''}">${icon(check.status==='passed'?'check':'info',15)}</span><div><strong>${esc(deploymentCheckLabel(check.id))}</strong><small>${esc(check.id==='configuration'?versionLabel(String(check.detail||'').split(' · ')[0]):check.id==='service'?say('The service is responding.','De service reageert.'):check.id==='package'?say('The script is ready to load.','Het script kan worden geladen.'):check.detail||'')}</small></div></div>`).join('')}</div>`:''}${status!=='not_checked'?`<div class="wk-check-walkthrough"><strong>${esc(verified?say('Deployment verified','Installatie gecontroleerd'):status==='expired'?say('Check expired. Start a new check.','Controle verlopen. Start opnieuw.'):say('Complete the website check','Voltooi de websitecontrole'))}</strong><ol>${[['sdk',say('Script loaded on your website','Script geladen op je website')],['submitted',say('Test submission intercepted','Testinvoer onderschept')],['rendered',say('Intervention displayed','Interventie getoond')]].map(([key,label])=>`<li class="${d.verification.steps[key]?'passed':''}">${icon(d.verification.steps[key]?'check':'clock',15)}${esc(label)}</li>`).join('')}</ol>${!verified&&status==='checking'&&d.testUrl?`<a class="button" href="${attr(d.testUrl)}" target="_blank" rel="noopener">${esc(say('Open website test','Websitetest openen'))}${icon('external',15)}</a><p>${esc(say('Submit test-trigger-red in the website search. This tab updates as each step succeeds.','Voer test-trigger-red in de zoekfunctie in. Dit tabblad toont de voortgang.'))}</p>`:''}</div>`:`<p class="wk-check-idle">${esc(say('The installation has not been verified in this session.','De installatie is in deze sessie nog niet gecontroleerd.'))}</p>`}</div></section>`;}
function deploymentCheckLabel(id){return ({service:say('Next Step service reachable','Next Step-service bereikbaar'),package:say('Browser package available','Browserpakket beschikbaar'),configuration:say('Published message available','Gepubliceerd bericht beschikbaar'),origin:say('Website origin configured','Website-oorsprong ingesteld')})[id]||id;}
async function refreshDeployment(){const id=state.siteId;try{const data=await api(modPath('/deployment'));if(id!==state.siteId)return;state.deployment=data;const target=document.querySelector('#deployment-status');if(target){const tmp=document.createElement('div');tmp.innerHTML=deploymentPanel();target.innerHTML=tmp.querySelector('#deployment-status').innerHTML;}if(data.verification.status==='checking'&&target)deploymentTimer=setTimeout(refreshDeployment,1200);}catch(error){notice(error.message,true);}}

