 if(entry.id==='discord')return {steps:[say('Create a Discord developer application and bot, then invite it to your test server with application-command and Manage Server permissions.','Maak een Discord-applicatie en bot en nodig deze uit op je testserver met rechten voor applicatiecommando’s en serverbeheer.'),say('Download and extract the bot package. Copy .env.example to .env and set the bot token, application ID and test guild ID locally.','Download en pak het botpakket uit. Kopieer .env.example naar .env en vul de bottoken, applicatie-ID en testserver-ID lokaal in.'),say(`Set BEFORE_API_ORIGIN to ${endpoint} and BEFORE_SITE_ID to ${site}. Use a reachable HTTPS BEFORE_PUBLIC_ORIGIN for links opened by remote Discord members.`,`Stel BEFORE_API_ORIGIN in op ${endpoint} en BEFORE_SITE_ID op ${site}. Gebruik een bereikbaar HTTPS-adres bij BEFORE_PUBLIC_ORIGIN voor andere Discord-gebruikers.`),say('Run the commands below. In Discord, use /before support or /before demo. A server moderator can run /before setup for the test AutoMod rule.','Voer onderstaande commando’s uit. Gebruik in Discord /before support of /before demo. Een servermoderator kan /before setup uitvoeren voor de AutoMod-testregel.')],code:`cp .env.example .env\nnpm install\nnpm run register\nnpm start`,verify:say('Connection is confirmed in your local bot process and Discord server. This browser does not store bot credentials.','Controleer de verbinding in je lokale botproces en Discord-server. Deze browser bewaart geen botgegevens.')};
 if(entry.id==='javascript')return {steps:[say('Add your website origin under Platform settings on the Install page.','Voeg je website-oorsprong toe bij Platforminstellingen op de installatiepagina.'),say('Copy the script below into your website layout before the closing body tag.','Kopieer het script hieronder vóór de afsluitende body-tag in je website.'),say('Call Before.intervene() when your existing moderation system makes a decision. The package does not supply a production detector.','Roep Before.intervene() aan bij een besluit van je bestaande moderatiesysteem. Het pakket bevat geen productiedetectie.'),say('Run the deployment check using the connected test website and test-trigger-red.','Voer de installatiecontrole uit met de aangesloten testwebsite en test-trigger-red.')],code:`<script src="${endpoint}/embed/before.js"\n  data-site="${site}" data-endpoint="${endpoint}" defer></script>\n\n<script>\n// Call from your existing moderation decision handler:\nfunction openBefore() {\n  return window.Before.intervene({ type: 'search', severity: 'high' });\n}\n</script>`,verify:say('The check confirms script load, test submission interception and the displayed intervention.','De controle bevestigt het laden van het script, het onderscheppen van de testinvoer en de getoonde interventie.')};
