 dialog.querySelector('[name="previewLanguage"]').onchange=event=>{state.previewLanguage=event.target.value;refreshPreview();};dialog.querySelector('#preview-reduced').onchange=event=>{state.reduced=event.target.checked;refreshPreview();};
