function previewStudy(study,{enrolKey,enrolSiteId,publishDefault=false}={}){
 const publication=study.publications?.at(-1)||study;const arms=publishDefault?[{id:'',name:state.draft.name,intervention:state.draft}]:publication.arms;let index=0;let language=state.editLanguage;let dispose=null;
 const dialog=document.createElement('dialog');dialog.className='experiment-dialog wk-variant-dialog';
 dialog.innerHTML=`<div class="dialog-heading"><div><h2>${esc(publishDefault?say('Review your message','Controleer je bericht'):publication.name||study.name)}</h2><p class="subtitle">${esc(publishDefault?say('Publishing updates your platform’s default message.','Publiceren werkt het standaardbericht van je platform bij.'):say('Review every step in both languages.','Controleer elke stap in beide talen.'))}</p></div><button type="button" class="icon-button" data-close aria-label="${attr(t('close'))}">${icon('close',18)}</button></div><div class="wk-modal-preview-tools"><div class="wk-arm-tabs">${arms.map((arm,i)=>`<button type="button" data-preview-arm="${i}" class="${i===0?'selected':''}">${esc(arm.id)} ${esc(arm.name)}</button>`).join('')}</div><label class="wk-inline-label">${esc(t('languages'))}<select id="review-language"><option value="en" ${language==='en'?'selected':''}>English</option><option value="nl" ${language==='nl'?'selected':''}>Nederlands</option></select></label></div><div id="review-message-preview" class="wk-shared-preview"></div><p class="wk-review-error form-error" role="alert"></p>${enrolKey?`<p class="wk-review-note">${esc(say('Enabling this version replaces your default message with these variants. New views are assigned automatically. Stopping participation restores your default.','Deze versie vervangt je standaardbericht door deze varianten. Nieuwe vertoningen worden automatisch toegewezen. Stoppen herstelt je standaardbericht.'))}</p><div class="dialog-actions"><button class="button" data-close>${esc(t('cancel'))}</button><button class="button primary" data-confirm-enrol data-testid="enrol-study">${esc(say('Enable study','Onderzoek inschakelen'))}</button></div>`:publishDefault?`<div class="dialog-actions"><button class="button" data-close>${esc(say('Keep editing','Verder bewerken'))}</button><button class="button primary" data-action="publish-default" data-testid="publish-intervention">${esc(t('publish'))}</button></div>`:''}`;
 const draw=()=>{dispose?.();const intervention=arms[index].intervention;dispose=renderPreview(dialog.querySelector('#review-message-preview'),intervention,{language,country:intervention.country||'NL',services:helpServices.filter(service=>service.country==='NL'&&service.verified),legalPack:legalPacks.find(pack=>pack.country==='NL')});dialog.querySelectorAll('[data-preview-arm]').forEach(button=>button.classList.toggle('selected',Number(button.dataset.previewArm)===index));};
 document.body.append(dialog);dialog.onclose=()=>{dispose?.();dialog.remove();};dialog.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>dialog.close());dialog.querySelectorAll('[data-preview-arm]').forEach(button=>button.onclick=()=>{index=Number(button.dataset.previewArm);draw();});dialog.querySelector('#review-language').onchange=event=>{language=event.target.value;draw();};
 dialog.querySelector('[data-confirm-enrol]')?.addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;try{state.studyPlatforms=await api(`/api/researcher/studies/${encodeURIComponent(state.study.id)}/platforms/${encodeURIComponent(enrolSiteId)}`,{method:'PUT',body:{studyRevision:enrolKey,enabled:true,confirmReplacement:true}});state.study=await api(`/api/researcher/studies/${encodeURIComponent(state.study.id)}`);dialog.close();renderCurrent();notice(t('changeSaved'));}catch(error){dialog.querySelector('.wk-review-error').textContent=error.message;button.disabled=false;}});
 dialog.showModal();draw();return dialog;
}

async function refreshLab(){
 const request=++state.labRequest;const routeToken=state.routeToken;
 try{const loaded=await loadResearchLab(api,state.labModel);if(request!==state.labRequest||routeToken!==state.routeToken||activeView()!=='lab')return;state.labData=loaded.data;state.labStudies=loaded.studies;state.labReport=loaded.report;const focus=document.activeElement?.dataset?.labSelect;const y=window.scrollY;renderCurrent();if(focus)document.querySelector(`[data-lab-select="${focus}"]`)?.focus({preventScroll:true});window.scrollTo(0,y);}
 catch(error){if(request===state.labRequest&&routeToken===state.routeToken)notice(error.message,true);}
}

function renderCurrent(){
 if(!state.role)return launcher();const view=activeView();let content;
 if(state.role==='moderator')content=({overview,intervention:moderatorEditor,integrations,content:contentView,docs:()=>integrationGuide(location.pathname.split('/').filter(Boolean)[2])}[view]||overview)();
 else content=view==='lab'?renderResearchLab({language:state.language,model:state.labModel,data:state.labData,studies:state.labStudies,report:state.labReport}):view==='editor'?researchEditor():view==='platforms'?studyPlatforms():view==='results'?analytics(true):studyList();
 shell(content);bindView();refreshPreview();
}

async function route(){
 const token=++state.routeToken;let parts=location.pathname.split('/').filter(Boolean);if(parts[0]==='moderator'&&['analytics','research'].includes(parts[1])){history.replaceState({},'','/moderator/overview');parts=['moderator','overview'];}
 document.body.classList.remove('navigation-open');
 if(parts[0]!=='moderator'&&parts[0]!=='researcher'){state.currentPath=location.pathname+location.search+location.hash;launcher();return;}
 state.role=parts[0]==='moderator'?'moderator':'researcher';loadingShell();
 try{
  await session(state.role);
  if(state.role==='moderator'){
   state.sites=await api('/api/moderator/sites');const requested=new URLSearchParams(location.search).get('site');if(requested&&state.sites.some(site=>site.id===requested))state.siteId=requested;
   if(!state.sites.some(site=>site.id===state.siteId))state.siteId=state.sites[0]?.id||'demo-forum';
   const context=`moderator:${state.siteId}`;if(state.reportContext!==context){state.reportContext=context;state.reportPublication='';}
   state.site=await api(modPath(''));const view=parts[1]||'overview';
   
   if(view==='overview'||view==='integrations')state.deployment=await api(modPath('/deployment')).catch(()=>null);
   if(view==='docs'&&parts[2]==='discord'){state.discord=await api('/api/moderator/discord');state.discordSettings=await api('/api/moderator/integrations/discord/config');}
   if(view==='intervention'){state.draft=structuredClone(await api(modPath('/draft')));state.dirty=false;state.builderPast=[];state.builderFuture=[];state.builderCheckpoint=null;state.selectedMessageBlock='main';state.previewLanguage=state.editLanguage;if(!state.draft.order.includes(state.editStage))state.editStage=state.draft.order[0];}
   
  }else{
   if(parts[1]==='lab'){const loaded=await loadResearchLab(api,state.labModel);state.labData=loaded.data;state.labStudies=loaded.studies;state.labReport=loaded.report;}
   else if(parts.length>=3){
    const context=`researcher:${parts[2]}`;if(state.reportContext!==context){state.reportContext=context;state.reportPublication='';}
    state.study=await api(`/api/researcher/studies/${encodeURIComponent(parts[2])}`);if(parts[3]==='platforms')state.studyPlatforms=await api(`/api/researcher/studies/${encodeURIComponent(parts[2])}/platforms`);state.selectedArm=Math.min(state.selectedArm,Math.max(0,state.study.arms.length-1));state.dirty=false;
    if(!state.study.arms[state.selectedArm].intervention.order.includes(state.editStage))state.editStage=state.study.arms[state.selectedArm].intervention.order[0];
    if(parts[3]==='results')state.report=await api(`/api/researcher/studies/${encodeURIComponent(state.study.id)}/metrics?${reportQuery()}`);
   }else state.studies=await api('/api/researcher/studies');
  }
  if(token!==state.routeToken)return;
  state.currentPath=location.pathname+location.search+location.hash;renderCurrent();document.querySelector('h1')?.focus({preventScroll:true});window.scrollTo(0,0);
  if(location.hash){const target=document.getElementById(location.hash.slice(1));if(target){if(target.tagName==='DETAILS')target.open=true;target.scrollIntoView({block:'start'});}}
 }catch(error){if(token!==state.routeToken)return;shell(errorView(error));}
}

function dirty(){state.dirty=true;if(state.role==='researcher'&&state.study&&state.study.status!=='ended')redistributeWeights();const marker=document.querySelector('#draft-indicator');if(marker)marker.textContent=t('unsaved');document.querySelectorAll('[data-action="save-default"],[data-action="save-study"],[data-action="review-default"],[data-action="publish-study"]').forEach(button=>button.disabled=false);}

function updateIntervention(target,name,value,checked){
  const [group,key]=name.split(':');
  if(group==='copy'){target[state.editLanguage][key]=value;}
  if(group==='intervention'&&key==='name')target.name=value;
  if(group==='option'){
    if(key==='order')target.order=structuredClone(target.layout==='plain'?ORDERS[2]:ORDERS[Number(value)]||ORDERS[0]);
    else if(key==='legal')target.legal=checked;
    else target[key]=value;
    if(key==='layout'&&value==='plain'){target.order=[...ORDERS[2]];target.motion.enabled=false;}
    if(key==='layout'&&value==='meaning')target.motion.enabled=false;
  }
  if(group==='motion'){
    target.motion||={enabled:false,transition:'fade',holdSeconds:5};
    target.motion[key]=key==='enabled'?checked:key==='holdSeconds'?Number(value):value;
    if(key==='enabled'&&checked){target.layout='scene';document.querySelector('[name="option:layout"]')?.setAttribute('value','scene');const select=document.querySelector('[name="option:layout"]');if(select)select.value='scene';}
  }
}

function applyPreset(preset){applyInterventionTemplate(interventionPreset(preset),local(MESSAGE_PRESETS.find(item=>item.id===preset).name));document.querySelector('.wk-message-presets').open=true;}
function replaceIntervention(target,replacement){for(const key of Object.keys(target))delete target[key];Object.assign(target,structuredClone(replacement));}
function applyInterventionTemplate(replacement,name){
 const target=currentIntervention();if(!target||(state.role==='researcher'&&state.study?.status==='ended'))return;
 if(state.role==='moderator'){
  rememberBuilder();const country=target.country;const customName=target.name!==DEFAULT_INTERVENTION.name&&!MODERATION_TEMPLATES.some(item=>Object.values(item.name).includes(target.name))?target.name:null;
  replaceIntervention(target,{...replacement,country,...(customName?{name:customName}:{})});state.selectedMessageBlock='main';state.messageInspectorTab='content';state.messageMode='build';
 }else{
  const arm=state.study.arms[state.selectedArm];state.presetUndo={studyId:state.study.id,armId:arm.id,armName:arm.name,intervention:structuredClone(target)};const defaultName=arm.name===target.name||/^Variant [A-D]$/.test(arm.name);replaceIntervention(target,replacement);if(defaultName)arm.name=name;
 }
 state.editStage=target.order[0];state.previewLanguage=state.editLanguage;dirty();renderCurrent();if(state.role==='moderator'){window.scrollTo(0,0);document.querySelector('h1')?.focus({preventScroll:true});}
}

function builderSnapshot(){return {intervention:structuredClone(state.draft),stage:state.editStage,block:state.selectedMessageBlock,template:state.selectedMessageTemplate};}
function updateBuilderHistoryButtons(){document.querySelector('[data-action="builder-undo"]')?.toggleAttribute('disabled',state.builderPast.length===0);document.querySelector('[data-action="builder-redo"]')?.toggleAttribute('disabled',state.builderFuture.length===0);}
function rememberBuilder(snapshot=builderSnapshot()){
 if(state.role!=='moderator')return;const previous=state.builderPast.at(-1);if(!previous||JSON.stringify(previous.intervention)!==JSON.stringify(snapshot.intervention)){state.builderPast.push(snapshot);if(state.builderPast.length>40)state.builderPast.shift();}state.builderFuture=[];updateBuilderHistoryButtons();
}
function rememberBuilderInput(input){
 if(state.role!=='moderator')return;const checkpoint=state.builderCheckpoint;if(checkpoint?.input===input&&!checkpoint.recorded){rememberBuilder(checkpoint.snapshot);checkpoint.recorded=true;}
}
function restoreBuilder(snapshot){state.draft=structuredClone(snapshot.intervention);state.editStage=state.draft.order.includes(snapshot.stage)?snapshot.stage:state.draft.order[0];state.selectedMessageBlock=snapshot.block||'main';state.selectedMessageTemplate=snapshot.template||null;state.builderCheckpoint=null;dirty();renderCurrent();}
function moveMessageBlock(from,to){
 const blocks=state.draft.blocks?.[state.editStage]||[];if(from<0||to<0||from>=blocks.length||to>=blocks.length||from===to)return;rememberBuilder();const [block]=blocks.splice(from,1);blocks.splice(to,0,block);state.selectedMessageBlock=block.id;dirty();renderCurrent();
}
function chooseMessageBlock(id,stage=state.editStage){
 if(state.role!=='moderator')return;state.editStage=stage;state.selectedMessageBlock=id;state.messageInspectorTab='content';state.builderTab='edit';renderCurrent();document.querySelector(id==='main'?'#default-editor input':'#default-editor textarea')?.focus({preventScroll:true});const preview=document.querySelector('#shared-preview');const selected=preview?.querySelector(`[data-message-block="${CSS.escape(id)}"]`);if(selected)preview.scrollTop+=selected.getBoundingClientRect().top-preview.getBoundingClientRect().top-40;
}
function previewModeratorTemplate(id){
 const metadata=MODERATION_TEMPLATES.find(item=>item.id===id);if(!metadata)return;const message=moderationTemplate(id);const dialog=document.createElement('dialog');dialog.className='experiment-dialog mb-template-preview-dialog';let dispose;let language=state.editLanguage;
 dialog.innerHTML=`<div class="dialog-heading"><div><p class="eyebrow">${esc(local(metadata.category))}</p><h2>${esc(local(metadata.name))}</h2><p class="subtitle">${esc(local(metadata.description))}</p></div><button type="button" class="icon-button" data-close aria-label="${attr(t('close'))}">${icon('close',18)}</button></div><div class="mb-preview-template-tools"><div class="segmented"><button type="button" data-template-language="en">English</button><button type="button" data-template-language="nl">Nederlands</button></div><button type="button" class="button primary" data-template-confirm>${esc(say('Use this template','Gebruik dit sjabloon'))}${icon('arrow',16)}</button></div><div id="template-preview" class="wk-shared-preview"></div>`;
 const draw=()=>{dispose?.();dialog.querySelectorAll('[data-template-language]').forEach(button=>button.classList.toggle('selected',button.dataset.templateLanguage===language));dispose=renderPreview(dialog.querySelector('#template-preview'),message,{language,country:state.draft.country,services:helpServices.filter(service=>service.country==='NL'&&service.verified),legalPack:legalPacks.find(pack=>pack.country==='NL')});};
 document.body.append(dialog);dialog.onclose=()=>{dispose?.();dialog.remove();};dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelectorAll('[data-template-language]').forEach(button=>button.onclick=()=>{language=button.dataset.templateLanguage;draw();});dialog.querySelector('[data-template-confirm]').onclick=()=>{dialog.close();applyInterventionTemplate(message,local(metadata.name));state.selectedMessageTemplate=id;};dialog.showModal();draw();
}

function bindModeratorBuilder(){
 const shell=document.querySelector('.mb-shell');if(!shell)return;
 shell.addEventListener('click',event=>{
  const button=event.target.closest('button');if(!button||button.disabled)return;
  if(button.dataset.messageMode){state.messageMode=button.dataset.messageMode;renderCurrent();}
  else if(button.dataset.templateFilter){state.messageTemplateFilter=button.dataset.templateFilter;renderCurrent();}
  else if(button.dataset.inspectorTab){state.messageInspectorTab=button.dataset.inspectorTab;renderCurrent();}
  else if(button.dataset.useTemplate){const id=button.dataset.useTemplate;const metadata=MODERATION_TEMPLATES.find(item=>item.id===id);applyInterventionTemplate(moderationTemplate(id),local(metadata.name));state.selectedMessageTemplate=id;}
  else if(button.dataset.previewTemplate)previewModeratorTemplate(button.dataset.previewTemplate);
  else if(button.dataset.selectBlock)chooseMessageBlock(button.dataset.selectBlock);
  else if(button.dataset.addBlock){const message=state.draft;const blocks=stageBlocks(message,state.editStage);if(blocks.length>=MAX_BLOCKS_PER_STAGE)return;rememberBuilder();message.blocks||={reflection:[],education:[],support:[]};const block=createMessageBlock(button.dataset.addBlock);message.blocks[state.editStage].push(block);state.selectedMessageBlock=block.id;state.messageInspectorTab='content';dirty();renderCurrent();document.querySelector('#default-editor textarea')?.focus({preventScroll:true});}
  else if(button.dataset.blockMove){const index=stageBlocks(state.draft,state.editStage).findIndex(block=>block.id===state.selectedMessageBlock);moveMessageBlock(index,index+Number(button.dataset.blockMove));}
 });
 let dragged=null;
 shell.querySelectorAll('[data-drag-block]').forEach(row=>{
  row.addEventListener('dragstart',event=>{dragged=row.dataset.dragBlock;row.classList.add('dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',dragged);});
  row.addEventListener('dragend',()=>{dragged=null;shell.querySelectorAll('.dragging,.drop-target').forEach(item=>item.classList.remove('dragging','drop-target'));});
  row.addEventListener('dragover',event=>{event.preventDefault();row.classList.add('drop-target');});row.addEventListener('dragleave',()=>row.classList.remove('drop-target'));
  row.addEventListener('drop',event=>{event.preventDefault();const id=dragged||event.dataTransfer.getData('text/plain');const blocks=stageBlocks(state.draft,state.editStage);moveMessageBlock(blocks.findIndex(block=>block.id===id),blocks.findIndex(block=>block.id===row.dataset.dragBlock));});
 });
}

function bindEditor(form){
 if(!form)return;form.addEventListener('submit',event=>event.preventDefault());
 form.addEventListener('focusin',event=>{if(state.role==='moderator'&&event.target.matches('input,textarea,select'))state.builderCheckpoint={input:event.target,snapshot:builderSnapshot(),recorded:false};});
 form.addEventListener('input',event=>{
  const input=event.target;if(input.dataset.blockText&&state.role==='moderator'){rememberBuilderInput(input);const block=stageBlocks(state.draft,state.editStage).find(item=>item.id===input.dataset.blockText);if(block){block[state.editLanguage]=input.value;dirty();const count=form.querySelector('[data-block-count]');if(count)count.textContent=`${input.value.length} / 600`;const summary=document.querySelector(`[data-select-block="${block.id}"] small`);if(summary)summary.textContent=input.value.slice(0,35);refreshPreview();}return;}if(!input.name)return;const [group,key]=input.name.split(':');
  if(group==='study'){state.study[key]=input.value;dirty();return;}
  if(group==='arm'){state.study.arms[state.selectedArm][key]=key==='weight'?Number(input.value):input.value;dirty();return;}
  if(input.name==='preset'){applyPreset(input.value);return;}
  const target=currentIntervention();if(!target)return;rememberBuilderInput(input);updateIntervention(target,input.name,input.value,input.checked);dirty();
  if(['option:order','motion:enabled','option:layout','option:country','option:appearance'].includes(input.name)){const advanced=document.querySelector('#advanced-settings')?.open;if(!target.order.includes(state.editStage))state.editStage=target.order[0];renderCurrent();if(advanced&&document.querySelector('#advanced-settings'))document.querySelector('#advanced-settings').open=true;}
  else refreshPreview();
 });
}

function bindCommon(){
 document.querySelector('#ui-language')?.addEventListener('change',event=>{state.language=event.target.value;renderCurrent();});
 document.querySelector('#site-selector')?.addEventListener('change',async event=>{const selected=event.target.value;if(!await allowLeave()){event.target.value=state.siteId;return;}state.siteId=selected;state.deployment=null;history.replaceState({},'',location.pathname+location.hash);route();});
}

function bindView(){
 if(state.role==='moderator'&&['integrations','docs'].includes(activeView()))disposeExtra.push(bindIntegrations({container:document.querySelector('#main'),language:state.language,site:state.site,endpoint:location.origin,discord:state.discord,discordSettings:state.discordSettings,discordOAuth:state.discordOAuth,api,onNavigate:go,onNotice:notice,onUpdated:value=>{if(value.discord)state.discord=value.discord;if(value.discordSettings)state.discordSettings=value.discordSettings;if(value.site){state.site=value.site;state.sites=state.sites.map(site=>site.id===value.site.id?value.site:site);}}}));
 if(state.role==='researcher'&&activeView()==='lab')disposeExtra.push(bindResearchLab({container:document.querySelector('#main'),language:state.language,model:state.labModel,data:state.labData,api,onRefresh:refreshLab,onNotice:notice}));
 bindModeratorBuilder();
 bindEditor(document.querySelector('#default-editor'));bindEditor(document.querySelector('#arm-editor'));bindEditor(document.querySelector('#study-meta'));
 document.querySelectorAll('[data-edit-language]').forEach(button=>button.onclick=()=>{state.editLanguage=button.dataset.editLanguage;state.previewLanguage=state.editLanguage;renderCurrent();});
 document.querySelectorAll('[data-edit-stage]').forEach(button=>button.onclick=()=>{state.editStage=button.dataset.editStage;if(state.role==='moderator'){state.selectedMessageBlock='main';state.messageInspectorTab='content';}renderCurrent();});
 document.querySelectorAll('[data-viewport]').forEach(button=>button.onclick=()=>{state.viewport=button.dataset.viewport;renderCurrent();});
 document.querySelectorAll('[data-builder-tab]').forEach(button=>{if(button.tagName==='BUTTON')button.onclick=()=>{state.builderTab=button.dataset.builderTab;renderCurrent();};});
 document.querySelectorAll('[data-composer-step]').forEach(button=>button.onclick=()=>{state.composerStep=button.dataset.composerStep;renderCurrent();});
 document.querySelectorAll('[data-arm]').forEach(button=>{button.dataset.testid='variant-select';button.onclick=()=>{state.selectedArm=Number(button.dataset.arm);state.editStage=state.study.arms[state.selectedArm].intervention.order[0];renderCurrent();};});
 document.querySelectorAll('[data-message-preset]').forEach(button=>button.onclick=()=>applyPreset(button.dataset.messagePreset));
 document.querySelectorAll('[data-experience-preset]').forEach(button=>button.onclick=()=>{const preset=EXPERIENCE_PRESETS.find(item=>item.id===button.dataset.experiencePreset);applyInterventionTemplate(experiencePreset(preset.id),local(preset.name));});
 for(const [id,key]of [['report-source','source'],['report-period','reportPeriod'],['report-publication','reportPublication']])document.getElementById(id)?.addEventListener('change',event=>{state[key]=event.target.value;route();});
 document.querySelector('#catalogue-filter')?.addEventListener('input',event=>{state.filter=event.target.value;document.querySelector('#catalogue-grid').innerHTML=catalogueCards();});
 document.querySelector('#catalogue-category')?.addEventListener('change',event=>{state.category=event.target.value;document.querySelector('#catalogue-grid').innerHTML=catalogueCards();});
 document.querySelector('#connection-form')?.addEventListener('submit',saveConnection);
 const markers={'publish-default':'publish-intervention','create-study':'new-study','publish-study':'publish-study','enrol':'enrol-study'};
 for(const[action,testid]of Object.entries(markers))document.querySelectorAll(`[data-action="${action}"]`).forEach(button=>button.dataset.testid=testid);
 if(state.deployment?.verification?.status==='checking'&&document.querySelector('#deployment-status'))deploymentTimer=setTimeout(refreshDeployment,1200);
}

async function saveConnection(event){
  event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const data=new FormData(form);const button=form.querySelector('button');setBusy(button,true);
  try{state.site=await api(modPath(''),{method:'PUT',body:{name:String(data.get('name')).trim(),origins:String(data.get('origins')).split(/[\n,]/).map(value=>value.trim()).filter(Boolean),returnUrl:String(data.get('returnUrl')).trim(),country:data.get('country')}});state.deployment=await api(modPath('/deployment'));renderCurrent();notice(t('changeSaved'));}
  catch(error){notice(error.message,true);}finally{setBusy(button,false);}
}
function studyPayload(study){return{name:study.name,hypothesis:study.hypothesis,primary:study.primary,countries:study.countries||['NL'],languages:study.languages||['en','nl'],arms:study.arms};}
function evenStudyPayload(study){const payload=studyPayload(study);const n=payload.arms.length;return {...payload,arms:payload.arms.map((arm,i)=>({...arm,weight:Math.floor(100/n)+(i<100%n?1:0)}))};}
function validateStudy(){
  const forms=[document.querySelector('#study-meta'),document.querySelector('#arm-editor')];if(forms.some(form=>form&&!form.reportValidity()))return false;
  if(state.study.arms.length<2||state.study.arms.length>4){notice(t('armLimit'),true);return false;}
  if(state.study.arms.reduce((sum,arm)=>sum+Number(arm.weight),0)!==100){notice(t('weightsInvalid'),true);document.querySelector('#weight-summary')?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return false;}
  return true;
}
async function saveDefault(button,publish=false){
  const form=document.querySelector('#default-editor');if(form&&!form.reportValidity())return;setBusy(button,true);
  try{
    state.draft=await api(modPath('/draft'),{method:'PUT',body:state.draft});
    if(publish){state.site=await api(modPath('/publish'),{method:'POST',body:{}});state.draft=structuredClone(state.site.draft||state.site.intervention);}
    state.site.draft=structuredClone(state.draft);state.dirty=false;document.querySelector('.wk-variant-dialog')?.close();renderCurrent();notice(publish?t('published'):t('saved'));return true;
  }catch(error){notice(error.message||t('saveFailed'),true);const reviewError=document.querySelector('.wk-review-error');if(reviewError)reviewError.textContent=error.message||t('saveFailed');setBusy(button,false);}
}
async function saveStudy(button,publish=false){
  if(!validateStudy())return;setBusy(button,true);
  try{state.study=await api(`/api/researcher/studies/${encodeURIComponent(state.study.id)}`,{method:'PUT',body:evenStudyPayload(state.study)});if(publish)state.study=await api(`/api/researcher/studies/${encodeURIComponent(state.study.id)}/publish`,{method:'POST',body:{}});state.dirty=false;renderCurrent();notice(publish?t('published'):t('saved'));}
  catch(error){notice(error.message||t('saveFailed'),true);setBusy(button,false);}
}

function openCreateStudy(){
 const dialog=document.createElement('dialog');dialog.className='experiment-dialog';const previous=document.activeElement;let presetId='reflection';
 const initial=createStudyPreset(presetId);
 dialog.innerHTML=`<form><div class="dialog-heading"><h2>${esc(t('create'))}</h2><button type="button" class="icon-button" data-close aria-label="${attr(t('close'))}">${icon('close')}</button></div>${select(say('Comparison preset','Vergelijkingssjabloon'),'studyPreset',presetId,STUDY_PRESETS.map(preset=>[preset.id,local(preset.name)]))}${field(say('Study name','Onderzoeksnaam'),'name','')}${field(t('hypothesis'),'hypothesis',initial.hypothesis,{area:true})}<p class="form-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button" data-close>${esc(t('cancel'))}</button><button type="submit" class="button primary">${esc(t('create'))}${icon('arrow',15)}</button></div></form>`;
 document.body.appendChild(dialog);dialog.onclose=()=>{dialog.remove();previous?.focus();};dialog.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>dialog.close());
 dialog.querySelector('[name="studyPreset"]').onchange=event=>{const last=createStudyPreset(presetId);presetId=event.target.value;const next=createStudyPreset(presetId);const name=dialog.querySelector('[name="name"]');if(!name.value||name.value===last.name)name.value=next.name;dialog.querySelector('[name="hypothesis"]').value=next.hypothesis;};
 dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const values=new FormData(form);const payload=createStudyPreset(String(values.get('studyPreset')),String(values.get('name')).trim());payload.hypothesis=String(values.get('hypothesis')).trim();const button=form.querySelector('[type="submit"]');setBusy(button,true);try{const study=await api('/api/researcher/studies',{method:'POST',body:payload});dialog.close();state.selectedArm=0;state.composerStep='setup';state.editStage=study.arms[0].intervention.order[0];go(`/researcher/studies/${encodeURIComponent(study.id)}/editor`);}catch(error){dialog.querySelector('.form-error').textContent=error.message;setBusy(button,false);}};
 dialog.showModal();
}

async function action(button){
  const name=button.dataset.action;
  if(name==='retry'){state.roleReady=null;return route();}
  if(name==='mobile-nav'){const open=document.body.classList.toggle('navigation-open');button.setAttribute('aria-expanded',String(open));return;}
  if(name==='connect-discord'){
    if(state.discordBusy)return;state.discordBusy=true;state.discordPolls=0;setBusy(button,true,say('Finishing setup…','Installatie afronden…'));
    const token=state.routeToken;
    try{const connection=await api('/api/moderator/discord/connect',{method:'POST',body:{}});if(token===state.routeToken)state.discord=connection;}
    catch{if(token===state.routeToken)state.discord={...state.discord,status:'error',checks:{...state.discord?.checks,gateway:false,commands:false,protection:false},errorCode:'service_unavailable'};}
    finally{state.discordBusy=false;if(token===state.routeToken){renderCurrent();document.querySelector('[data-action="connect-discord"]')?.focus({preventScroll:true});}}return;
  }
  if(name==='copy-discord-command'){
    try{await navigator.clipboard.writeText(button.dataset.command);notice(t('copied'));}catch{notice(say('Select the command and copy it manually.','Selecteer het commando en kopieer het handmatig.'),true);}return;
  }
  if(name==='builder-undo'){if(state.builderPast.length){state.builderFuture.push(builderSnapshot());restoreBuilder(state.builderPast.pop());}return;}
  if(name==='builder-redo'){if(state.builderFuture.length){state.builderPast.push(builderSnapshot());restoreBuilder(state.builderFuture.pop());}return;}
  if(name==='delete-message-block'){const blocks=state.draft.blocks?.[state.editStage]||[];const index=blocks.findIndex(block=>block.id===state.selectedMessageBlock);if(index>=0){rememberBuilder();blocks.splice(index,1);state.selectedMessageBlock='main';dirty();renderCurrent();}return;}
  if(name==='create-study')return openCreateStudy();
  if(name==='save-default')return saveDefault(button);
  if(name==='publish-default')return saveDefault(button,true);
  if(name==='review-default'){const form=document.querySelector('#default-editor');if(form&&!form.reportValidity())return;return previewStudy({arms:[]},{publishDefault:true});}
  if(name==='preview-draft-study')return previewStudy({...state.study,publications:[]});
  if(name==='preview-default')return moderatorPreview();
  if(name==='review-platform-enrol'){const key=state.study.publications?.at(-1)?.key;if(key)return previewStudy(state.study,{enrolKey:key,enrolSiteId:button.dataset.siteId});return;}
  if(name==='withdraw-platform'){setBusy(button,true);try{state.studyPlatforms=await api(`/api/researcher/studies/${encodeURIComponent(state.study.id)}/platforms/${encodeURIComponent(button.dataset.siteId)}`,{method:'PUT',body:{studyRevision:button.dataset.studyRevision||state.study.publications.at(-1).key,enabled:false}});state.study=await api(`/api/researcher/studies/${encodeURIComponent(state.study.id)}`);renderCurrent();}catch(error){notice(error.message,true);setBusy(button,false);}return;}
  if(name==='undo-message-preset'){if(state.presetUndo){replaceIntervention(currentIntervention(),state.presetUndo.intervention);state.study.arms[state.selectedArm].name=state.presetUndo.armName;state.presetUndo=null;state.editStage=currentIntervention().order[0];dirty();renderCurrent();}return;}
  if(name==='check-deployment'){setBusy(button,true);try{state.deployment=await api(modPath('/deployment'),{method:'POST',body:{}});renderCurrent();document.querySelector('#deployment')?.scrollIntoView({block:'start'});}catch(error){notice(error.message,true);setBusy(button,false);}return;}
  if(name==='save-study')return saveStudy(button);
  if(name==='publish-study')return saveStudy(button,true);
  if(name==='reset-draft'){state.draft=structuredClone(state.site.draft||state.site.intervention);state.dirty=false;renderCurrent();return;}
  if(name==='add-arm'){
    if(state.study.arms.length>=4)return;const nextId=['A','B','C','D'].find(id=>!state.study.arms.some(arm=>arm.id===id));state.study.arms.push({id:nextId,name:`${t('variant')} ${nextId}`,weight:10,intervention:structuredClone(DEFAULT_INTERVENTION)});redistributeWeights();state.selectedArm=state.study.arms.length-1;dirty();renderCurrent();return;
  }
  if(name==='remove-arm'){if(state.study.arms.length<=2)return;state.study.arms.splice(state.selectedArm,1);state.selectedArm=0;redistributeWeights();dirty();renderCurrent();return;}
  if(name==='copy-guide'){
    try{await navigator.clipboard.writeText(document.querySelector('#guide-code').textContent);button.innerHTML=icon('check',17);button.setAttribute('aria-label',t('copied'));notice(t('copied'));}catch{notice(say('Select the code and copy it manually.','Selecteer de code en kopieer deze handmatig.'),true);}return;
  }
  if(name==='export'){
    if(state.role!=='researcher')return;const path=`/api/researcher/studies/${encodeURIComponent(state.study.id)}/export`;const anchor=document.createElement('a');anchor.href=`${path}?${reportQuery()}`;anchor.download='before-aggregate-results.csv';anchor.click();return;
  }
  setBusy(button,true);
  try{
    if(name==='revert-default'){state.site=await api(modPath('/revert'),{method:'POST',body:{}});state.draft=structuredClone(state.site.draft||state.site.intervention);state.dirty=false;}
    
    if(name==='study-status'&&!await allowLeave())return;
    if(name==='study-status')state.study=await api(`/api/researcher/studies/${encodeURIComponent(state.study.id)}/status`,{method:'PATCH',body:{status:button.dataset.status}});
    if(name==='duplicate-study'){const payload=evenStudyPayload(structuredClone(state.study));payload.name=`${payload.name} (${say('copy','kopie')})`;const created=await api('/api/researcher/studies',{method:'POST',body:payload});state.selectedArm=0;go(`/researcher/studies/${encodeURIComponent(created.id)}/editor`);return;}
    renderCurrent();notice(t('changeSaved'));
  }catch(error){notice(error.message,true);setBusy(button,false);}
}

function redistributeWeights(){const count=state.study.arms.length;state.study.arms.forEach((arm,i)=>arm.weight=Math.floor(100/count)+(i<100%count?1:0));}

document.addEventListener('click',event=>{
  const info=event.target.closest('[data-info]');if(info){if(!['workspace','report','preview','allocation','engagement','platforms'].includes(info.dataset.info))return;event.preventDefault();if(info.dataset.info==='preview')previewOptions();else if(info.dataset.info==='platforms')openInfoDialog({title:say('Platform approval','Platformtoestemming'),body:`<p>${esc(say('This local workspace lets its operator connect the three owned test platforms. Enabling a study approves exactly the reviewed publication; later edits never replace it automatically.','Deze lokale werkruimte laat de beheerder de drie eigen testplatforms verbinden. Inschakelen geldt alleen voor de gecontroleerde publicatie; latere wijzigingen vervangen die niet automatisch.'))}</p><p>${esc(say('A real platform owner must authorise participation. Researcher access alone is not permission to enrol an external platform.','De eigenaar van een echt platform moet toestemming geven. Toegang als onderzoeker geeft geen toestemming om een extern platform aan te sluiten.'))}</p>`});else if(info.dataset.info==='engagement')openInfoDialog({title:say('How engagement is measured','Hoe betrokkenheid wordt gemeten'),body:`<p>${esc(say('Visible ≥30s is the share of recorded journeys with at least 30 seconds in the foreground before the first help-link click, exit or navigation away. Visits still in progress are excluded.','Zichtbaar ≥30s is het aandeel geregistreerde routes met minstens 30 seconden op de voorgrond vóór de eerste klik op een hulplink, afsluiting of vertrek. Lopende bezoeken tellen nog niet mee.'))}</p><p>${esc(say('Scroll and message-end rates use measured views of the information step. Scrolling requires a user action. A message end can already be visible on a short page; visibility does not establish reading or comprehension.','Scroll- en berichteindepercentages gebruiken gemeten weergaven van de informatiestap. Scrollen vereist een gebruikersactie. Op een korte pagina kan het berichteinde al zichtbaar zijn; zichtbaarheid bewijst niet dat de tekst is gelezen of begrepen.'))}</p><p>${esc(say('Each cell shows a percentage and its eligible count. Small groups remain hidden. No return-visitor identities or browsing histories are collected.','Elke cel toont een percentage en het bijbehorende aantal. Kleine groepen blijven afgeschermd. Er worden geen terugkerende bezoekers geïdentificeerd of browsegeschiedenissen verzameld.'))}</p>`});else if(info.dataset.info==='allocation')openInfoDialog({title:say('How allocation works','Hoe toewijzing werkt'),body:`<p>${esc(say('On every platform opted into this study version, each new intervention view is randomly assigned using these weights. The study results combine those aggregate outcomes.','Op elk platform dat deze onderzoeksversie heeft ingeschakeld, krijgt elke nieuwe interventie willekeurig een variant volgens deze verdeling. De resultaten combineren die geaggregeerde uitkomsten.'))}</p><p>${esc(say('Assignment is per exposure. No visitor identifiers, profiles or persistent assignment cookies are used.','Toewijzing gebeurt per vertoning. Er worden geen bezoekersidentiteiten, profielen of blijvende toewijzingscookies gebruikt.'))}</p>`});else aboutWorkspace(info.dataset.info);return;}
  const button=event.target.closest('[data-action]');if(button){event.preventDefault();if(!button.disabled)action(button);return;}
  const anchor=event.target.closest('a[data-nav]');if(!anchor||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey||anchor.target==='_blank')return;event.preventDefault();const url=new URL(anchor.href);go(url.pathname+url.search+url.hash);
});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.body.classList.remove('navigation-open');});
window.addEventListener('popstate',async()=>{if(await allowLeave())route();else history.pushState({},'',state.currentPath);});
window.addEventListener('beforeunload',event=>{if(state.dirty){event.preventDefault();event.returnValue='';}});
route();
